{"command":"cat << 'EOF' > test_idx.c
#include <stdio.h>
#include <stdlib.h>
#include <lzma.h>

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    if (size < 12) { fclose(f); return 1; }

    uint8_t footer[12];
    fseek(f, size - 12, SEEK_SET);
    fread(footer, 1, 12, f);

    lzma_stream_flags flags;
    lzma_ret ret = lzma_stream_footer_decode(&flags, footer);
    if (ret != LZMA_OK) {
        printf("footer decode failed: %d\n", ret);
        fclose(f);
        return 1;
    }
    printf("index_backward_size: %llu, check: %d\n",
           (unsigned long long)flags.backward_size, flags.check);

    long index_size = flags.backward_size;
    fseek(f, size - 12 - index_size, SEEK_SET);
    uint8_t *index_buf = malloc(index_size);
    fread(index_buf, 1, index_size, f);

    lzma_index *idx = NULL;
    uint64_t memlimit = UINT64_MAX;
    size_t in_pos = 0;
    ret = lzma_index_buffer_decode(&idx, &memlimit, NULL, index_buf, &in_pos, index_size);
    if (ret != LZMA_OK) {
        printf("index buffer decode failed: %d\n", ret);
        free(index_buf);
        fclose(f);
        return 1;
    }

    printf("stream count: %llu, block count: %llu, comp size: %llu, uncomp size: %llu\n",
           (unsigned long long)lzma_index_stream_count(idx),
           (unsigned long long)lzma_index_block_count(idx),
           (unsigned long long)lzma_index_file_size(idx),
           (unsigned long long)lzma_index_uncompressed_size(idx));

    lzma_index_end(idx, NULL);
    free(index_buf);
    fclose(f);
    return 0;
}
EOF
gcc test_idx.c -llzma -o test_idx
./test_idx /tmp/test_xz/robot_test.txt.xz"}

