{"command":"cat << 'EOF' > test_idx3.c
#include <stdio.h>
#include <stdlib.h>
#include <lzma.h>

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 1;

    fseek(f, 12, SEEK_SET);
    uint8_t hlen_byte;
    fread(&hlen_byte, 1, 1, f);
    size_t hlen = (hlen_byte + 1) * 4;

    fseek(f, 12, SEEK_SET);
    uint8_t *hbuf = malloc(hlen);
    fread(hbuf, 1, hlen, f);

    lzma_filter filters[LZMA_FILTERS_MAX + 1];
    lzma_block block;
    block.version = 0;
    block.check = LZMA_CHECK_CRC64;
    block.filters = filters;

    lzma_ret ret = lzma_block_header_decode(&block, NULL, hbuf);
    printf("lzma_block_header_decode ret: %d, header_size: %u, compressed_size: %llu, uncompressed_size: %llu\n",
           ret, block.header_size, (unsigned long long)block.compressed_size, (unsigned long long)block.uncompressed_size);

    for (int i = 0; filters[i].id != LZMA_VLI_UNKNOWN; i++) {
        printf("Filter %d: ID 0x%llx\n", i, (unsigned long long)filters[i].id);
        if (filters[i].id == LZMA_FILTER_LZMA2) {
            lzma_options_lzma *opt = filters[i].options;
            printf("  dict_size: %u\n", opt->dict_size);
        }
    }

    free(hbuf);
    fclose(f);
    return 0;
}
EOF
gcc test_idx3.c -llzma -o test_idx3
./test_idx3 /tmp/test_xz/robot_test.txt.xz"}

