void print_filters_help(void) {
    printf(
"Filter chains are set using the --filters=FILTERS or --filters1=FILTERS ...\n"
"--filters9=FILTERS options. Each filter in the chain can be separated by\n"
"spaces or '--'. Alternatively a preset <0-9>[e] can be specified instead of\n"
"a filter chain.\n"
"\n"
"The supported filters and their options are:\n"
"lzma2:preset=<0-9[e]>,dict=<4KiB-1536MiB>,lc=<0-4>,lp=<0-4>,pb=<0-4>,mode=<fast|normal>,nice=<2-273>,mf=<hc3|hc4|bt2|bt3|bt4>,depth=<0-4294967295>\n"
"x86:start=<0-4294967295>\n"
"arm:start=<0-4294967295>\n"
"armthumb:start=<0-4294967295>\n"
"arm64:start=<0-4294967295>\n"
"riscv:start=<0-4294967295>\n"
"powerpc:start=<0-4294967295>\n"
"ia64:start=<0-4294967295>\n"
"sparc:start=<0-4294967295>\n"
"delta:dist=<1-256>\n"
    );
}

void print_info_memory(void) {
    uint64_t ram = get_hardware_ram();
    uint32_t threads = get_hardware_threads();
    uint64_t default_mt = ram / 4;

    if (g_opts.robot) {
        printf("%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu32 "\n",
               ram,
               g_opts.memlimit_compress,
               g_opts.memlimit_decompress,
               g_opts.memlimit_mt_decompress ? g_opts.memlimit_mt_decompress : default_mt,
               default_mt,
               threads);
        return;
    }

    printf("Hardware information:\n");
    printf("  Amount of physical memory (RAM):  %" PRIu64 " MiB (%" PRIu64 " B)\n",
           ram / (1024 * 1024), ram);
    printf("  Number of processor threads:      %" PRIu32 "\n\n", threads);

    printf("Memory usage limits:\n");
    if (g_opts.memlimit_compress == 0) {
