{"command":"cat << 'EOF' > src/file_io.c
#include "file_io.h"
#include <fcntl.h>

static char *g_current_dst_file = NULL;

static void signal_handler(int sig) {
    if (g_current_dst_file) {
        unlink(g_current_dst_file);
    }
    _exit(1);
}

void cleanup_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);
}

char *get_dest_name(const char *src, operation_mode_t mode, file_format_t format, const char *custom_suffix) {
    size_t len = strlen(src);
    if (mode == MODE_COMPRESS) {
        const char *suf = ".xz";
        if (custom_suffix) {
            suf = custom_suffix;
        } else if (format == FORMAT_LZMA) {
            suf = ".lzma";
        }

        char *dst = malloc(len + strlen(suf) + 1);
        sprintf(dst, "%s%s", src, suf);
        return dst;
    } else { // DECOMPRESS or TEST or LIST
        if (custom_suffix) {
            size_t suflen = strlen(custom_suffix);
            if (len > suflen && strcmp(src + len - suflen, custom_suffix) == 0) {
                char *dst = strdup(src);
                dst[len - suflen] = '\0';
                return dst;
            }
        } else {
            if (len > 3 && strcmp(src + len - 3, ".xz") == 0) {
                char *dst = strdup(src);
                dst[len - 3] = '\0';
                return dst;
            }
            if (len > 5 && strcmp(src + len - 5, ".lzma") == 0) {
                char *dst = strdup(src);
                dst[len - 5] = '\0';
                return dst;
            }
            if (len > 4 && strcmp(src + len - 4, ".txz") == 0) {
                char *dst = malloc(len - 4 + 5); // replace .txz with .tar
                strncpy(dst, src, len - 4);
                strcpy(dst + len - 4, ".tar");
                return dst;
            }
            if (len > 4 && strcmp(src + len - 4, ".tlz") == 0) {
                char *dst = malloc(len - 4 + 5); // replace .tlz with .tar
                strncpy(dst, src, len - 4);
                strcpy(dst + len - 4, ".tar");
                return dst;
            }
        }
        return NULL;
    }
}

int check_input_file(const char *src, struct stat *st) {
    if (strcmp(src, "-") == 0) {
        if (fstat(STDIN_FILENO, st) != 0) return -1;
        return 0;
    }

    if (lstat(src, st) != 0) {
        if (g_opts.quiet < 2) {
            fprintf(stderr, "%s: %s: %s\n", g_opts.progname, src, strerror(errno));
        }
        return -1;
    }

    if (S_ISDIR(st->st_mode)) {
        if (g_opts.quiet < 1) {
            fprintf(stderr, "%s: %s: Is a directory, skipping\n", g_opts.progname, src);
        }
        return -2; // warning / skip
    }

    if (S_ISLNK(st->st_mode) && !g_opts.force) {
        if (g_opts.quiet < 1) {
            fprintf(stderr, "%s: %s: Is a symbolic link, skipping\n", g_opts.progname, src);
        }
        return -2;
    }

    if (!S_ISREG(st->st_mode) && !g_opts.force) {
        if (g_opts.quiet < 1) {
            fprintf(stderr, "%s: %s: Not a regular file, skipping\n", g_opts.progname, src);
        }
        return -2;
    }

    if (st->st_nlink > 1 && !g_opts.force) {
        if (g_opts.quiet < 1) {
            fprintf(stderr, "%s: %s: Input file has more than one hard link, skipping\n", g_opts.progname, src);
        }
        return -2;
    }

    return 0;
}

int open_output_file(const char *dst, struct stat *src_st, bool force) {
    if (!dst || strcmp(dst, "-") == 0) {
        return STDOUT_FILENO;
    }

    struct stat st;
    if (stat(dst, &st) == 0 && !force) {
        if (g_opts.quiet < 2) {
            fprintf(stderr, "%s: %s: File exists\n", g_opts.progname, dst);
        }
        return -1;
    }

    int flags = O_WRONLY | O_CREAT | (force ? O_TRUNC : O_EXCL);
    mode_t mode = src_st ? (src_st->st_mode & 0777) : 0666;

    int fd = open(dst, flags, mode);
    if (fd < 0) {
        if (g_opts.quiet < 2) {
            fprintf(stderr, "%s: %s: %s\n", g_opts.progname, dst, strerror(errno));
        }
        return -1;
    }

    g_current_dst_file = (char *)dst;
    return fd;
}

void set_file_attrs(int dst_fd, const char *dst_name, const struct stat *src_st) {
    if (!src_st || dst_fd == STDOUT_FILENO) return;

    g_current_dst_file = NULL;

    fchmod(dst_fd, src_st->st_mode & 0777);
    fchown(dst_fd, src_st->st_uid, src_st->st_gid);

    struct timeval tv[2];
    tv[0].tv_sec = src_st->st_atime;
    tv[0].tv_usec = 0;
    tv[1].tv_sec = src_st->st_mtime;
    tv[1].tv_usec = 0;
    futimes(dst_fd, tv);
}
EOF"}

