#include "coder.h"

void format_size(uint64_t bytes, char *buf, size_t buf_size, bool human) {
    if (!human) {
        snprintf(buf, buf_size, "%" PRIu64 " B", bytes);
        return;
    }

    if (bytes < 1024) {
        snprintf(buf, buf_size, "%" PRIu64 " B", bytes);
    } else if (bytes < 1024ULL * 1024ULL) {
        snprintf(buf, buf_size, "%.1f KiB", (double)bytes / 1024.0);
    } else if (bytes < 1024ULL * 1024ULL * 1024ULL) {
        snprintf(buf, buf_size, "%.1f MiB", (double)bytes / (1024.0 * 1024.0));
    } else {
        snprintf(buf, buf_size, "%.1f GiB", (double)bytes / (1024.0 * 1024.0 * 1024.0));
    }
}

static void print_verbose_ratio(const char *filename, uint64_t in_bytes, uint64_t out_bytes, operation_mode_t mode) {
    char in_str[32], out_str[32];
    uint64_t comp_bytes = (mode == MODE_COMPRESS) ? out_bytes : in_bytes;
    uint64_t uncomp_bytes = (mode == MODE_COMPRESS) ? in_bytes : out_bytes;

    format_size(comp_bytes, in_str, sizeof(in_str), true);
    format_size(uncomp_bytes, out_str, sizeof(out_str), true);

    if (uncomp_bytes == 0) {
        fprintf(stderr, "%s: %s / %s = ---\n", filename, in_str, out_str);
    } else {
        double ratio = (double)comp_bytes / (double)uncomp_bytes;
        fprintf(stderr, "%s: %s / %s = %.3f\n", filename, in_str, out_str, ratio);
    }
}

int code_stream(int in_fd, int out_fd, const char *src_name, const char *dst_name) {
    lzma_stream strm = LZMA_STREAM_INIT;
    lzma_ret ret = LZMA_OK;

    if (g_opts.mode == MODE_COMPRESS) {
        if (g_opts.format == FORMAT_LZMA) {
            lzma_options_lzma opt;
            lzma_lzma_preset(&opt, g_opts.preset | (g_opts.extreme ? LZMA_PRESET_EXTREME : 0));
            ret = lzma_alone_encoder(&strm, &opt);
        } else if (g_opts.format == FORMAT_RAW) {
            ret = lzma_raw_encoder(&strm, g_opts.filters);
        } else { // XZ or AUTO
            if (g_opts.threads > 1 || (g_opts.threads == 0 && get_hardware_threads() > 1)) {
                lzma_mt mt = {
                    .flags = 0,
                    .threads = g_opts.threads == 0 ? get_hardware_threads() : g_opts.threads,
                    .block_size = g_opts.block_size,
                    .timeout = g_opts.flush_timeout,
                    .preset = g_opts.preset | (g_opts.extreme ? LZMA_PRESET_EXTREME : 0),
                    .check = g_opts.check,
                    .filters = g_opts.custom_filters ? g_opts.filters : NULL
                };
                ret = lzma_stream_encoder_mt(&strm, &mt);
            } else {
                if (g_opts.custom_filters) {
                    ret = lzma_stream_encoder(&strm, g_opts.filters, g_opts.check);
                } else {
                    ret = lzma_easy_encoder(&strm, g_opts.preset | (g_opts.extreme ? LZMA_PRESET_EXTREME : 0), g_opts.check);
                }
            }
        }
    } else { // DECOMPRESS or TEST
        uint64_t memlimit = g_opts.memlimit_decompress ? g_opts.memlimit_decompress : UINT64_MAX;
        uint32_t flags = LZMA_TELL_UNSUPPORTED_CHECK;
        if (!g_opts.single_stream) {
            flags |= LZMA_CONCATENATED;
        }
        if (g_opts.ignore_check) {
            flags |= LZMA_IGNORE_CHECK;
        }

        if (g_opts.format == FORMAT_LZMA) {
            ret = lzma_alone_decoder(&strm, memlimit);
        } else if (g_opts.format == FORMAT_RAW) {
            ret = lzma_raw_decoder(&strm, g_opts.filters);
        } else if (g_opts.format == FORMAT_XZ) {
            ret = lzma_stream_decoder(&strm, memlimit, flags);
        } else { // AUTO
            ret = lzma_auto_decoder(&strm, memlimit, flags);
        }
    }

    if (ret != LZMA_OK) {
        if (g_opts.quiet < 2) {
            fprintf(stderr, "%s: %s: Initialization failed (%d)\n", g_opts.progname, src_name, ret);
        }
        return -1;
    }

    uint8_t inbuf[65536];
    uint8_t outbuf[65536];

    strm.next_in = NULL;
    strm.avail_in = 0;
    strm.next_out = outbuf;
    strm.avail_out = sizeof(outbuf);

    lzma_action action = LZMA_RUN;
    uint64_t total_in = 0;
    uint64_t total_out = 0;

    while (1) {
        if (strm.avail_in == 0 && action == LZMA_RUN) {
            ssize_t n = read(in_fd, inbuf, sizeof(inbuf));
            if (n < 0) {
                if (g_opts.quiet < 2) {
                    fprintf(stderr, "%s: %s: %s\n", g_opts.progname, src_name, strerror(errno));
                }
                lzma_end(&strm);
                return -1;
            }
            if (n == 0) {
                action = LZMA_FINISH;
            } else {
                strm.next_in = inbuf;
                strm.avail_in = n;
                total_in += n;
            }
        }

        ret = lzma_code(&strm, action);

        size_t write_size = sizeof(outbuf) - strm.avail_out;
        if (write_size > 0) {
            if (g_opts.mode != MODE_TEST && out_fd >= 0) {
                ssize_t written = write(out_fd, outbuf, write_size);
                if (written < 0 || (size_t)written != write_size) {
                    if (g_opts.quiet < 2) {
                        fprintf(stderr, "%s: %s: Write error: %s\n", g_opts.progname, dst_name ? dst_name : "stdout", strerror(errno));
                    }
                    lzma_end(&strm);
                    return -1;
                }
            }
            total_out += write_size;
            strm.next_out = outbuf;
            strm.avail_out = sizeof(outbuf);
        }

        if (ret == LZMA_STREAM_END) {
            break;
        }

        if (ret != LZMA_OK) {
            if (g_opts.quiet < 2) {
                switch (ret) {
                    case LZMA_MEM_ERROR:
                        fprintf(stderr, "%s: %s: Memory usage limit reached\n", g_opts.progname, src_name);
                        break;
                    case LZMA_FORMAT_ERROR:
                        fprintf(stderr, "%s: %s: File format not recognized\n", g_opts.progname, src_name);
                        break;
                    case LZMA_DATA_ERROR:
                        fprintf(stderr, "%s: %s: Compressed data is corrupt\n", g_opts.progname, src_name);
                        break;
                    case LZMA_BUF_ERROR:
                        fprintf(stderr, "%s: %s: Unexpected end of input\n", g_opts.progname, src_name);
                        break;
                    default:
                        fprintf(stderr, "%s: %s: Decoder error (%d)\n", g_opts.progname, src_name, ret);
                        break;
                }
            }
            lzma_end(&strm);
            return -1;
        }
    }

    lzma_end(&strm);

    if (g_opts.verbose > 0 && g_opts.quiet == 0) {
        print_verbose_ratio(src_name, total_in, total_out, g_opts.mode);
    }

    return 0;
}
EOF"}

