static void parse_env_var(const char *env_name) {
    const char *env = getenv(env_name);
    if (!env || !*env) return;

    char *str = strdup(env);
    int capacity = 16;
    int argc = 0;
    char **argv = malloc(capacity * sizeof(char *));

    argv[argc++] = strdup(g_opts.progname);

    char *token = strtok(str, " \t\n");
    while (token) {
        if (argc >= capacity - 1) {
            capacity *= 2;
            argv = realloc(argv, capacity * sizeof(char *));
        }
        argv[argc++] = strdup(token);
        token = strtok(NULL, " \t\n");
    }
    argv[argc] = NULL;

    parse_args(argc, argv);

    for (int i = 0; i < argc; i++) free(argv[i]);
    free(argv);
    free(str);
}

static int process_single_file(const char *src) {
    struct stat src_st;
    int check_ret = check_input_file(src, &src_st);
    if (check_ret == -1) {
        g_opts.exit_status = 1;
        return -1;
    }
    if (check_ret == -2) {
        if (g_opts.exit_status == 0 && !g_opts.no_warn) {
            g_opts.exit_status = 2;
        }
        return 0;
    }

    bool is_stdin = (strcmp(src, "-") == 0);

    if (g_opts.mode == MODE_COMPRESS && is_stdin && isatty(STDOUT_FILENO)) {
        fprintf(stderr, "%s: Compressed data cannot be written to a terminal\n", g_opts.progname);
        fprintf(stderr, "%s: Try '%s --help' for more information.\n", g_opts.progname, g_opts.progname);
        exit(1);
    }

    if (g_opts.mode == MODE_DECOMPRESS && is_stdin && isatty(STDIN_FILENO)) {
        fprintf(stderr, "%s: Compressed data cannot be read from a terminal\n", g_opts.progname);
        exit(1);
    }

    int in_fd = STDIN_FILENO;
    if (!is_stdin) {
        in_fd = open(src, O_RDONLY);
        if (in_fd < 0) {
            if (g_opts.quiet < 2) {
                fprintf(stderr, "%s: %s: %s\n", g_opts.progname, src, strerror(errno));
            }
            g_opts.exit_status = 1;
            return -1;
        }
    }

    char *dst_name = NULL;
    int out_fd = STDOUT_FILENO;

    if (g_opts.mode == MODE_COMPRESS || g_opts.mode == MODE_DECOMPRESS) {
        if (!is_stdin && !g_opts.opt_stdout) {
            dst_name = get_dest_name(src, g_opts.mode, g_opts.format, g_opts.suffix);
            if (!dst_name) {
                if (g_opts.quiet < 2) {
                    fprintf(stderr, "%s: %s: File format not recognized\n", g_opts.progname, src);
                }
                if (!is_stdin) close(in_fd);
                g_opts.exit_status = 1;
                return -1;
            }
            out_fd = open_output_file(dst_name, &src_st, g_opts.force);
            if (out_fd < 0) {
                if (!is_stdin) close(in_fd);
                free(dst_name);
                g_opts.exit_status = 1;
                return -1;
            }
        }
    }

    int code_res = code_stream(in_fd, out_fd, src, dst_name);

    if (!is_stdin) close(in_fd);

    if (code_res != 0) {
        if (out_fd >= 0 && out_fd != STDOUT_FILENO) {
            close(out_fd);
            if (dst_name) unlink(dst_name);
        }
        if (dst_name) free(dst_name);
        g_opts.exit_status = 1;
        return -1;
    }

    if (out_fd >= 0 && out_fd != STDOUT_FILENO) {
        set_file_attrs(out_fd, dst_name, &src_st);
        close(out_fd);
        if (!g_opts.keep) {
            unlink(src);
        }
    }

    if (dst_name) free(dst_name);
    return 0;
}

int main(int argc, char **argv) {
    cleanup_signals();
    init_options(argv[0]);

    parse_env_var("XZ_DEFAULTS");
    parse_env_var("XZ_OPT");
    parse_args(argc, argv);

    if (g_opts.format == FORMAT_RAW && g_opts.mode == MODE_COMPRESS && !g_opts.suffix && !g_opts.opt_stdout) {
        fprintf(stderr, "%s: With --format=raw, --suffix=.SUF is required unless writing to stdout\n", g_opts.progname);
        exit(1);
    }

    if (g_opts.format == FORMAT_LZIP && g_opts.mode == MODE_COMPRESS) {
        fprintf(stderr, "%s: Compression of lzip files (.lz) is not supported\n", g_opts.progname);
        exit(1);
    }

    int file_args_start = optind;
    int num_files = argc - file_args_start;

    if (g_opts.files_from) {
        FILE *f_list = stdin;
        if (strcmp(g_opts.files_from, "-") != 0) {
            f_list = fopen(g_opts.files_from, "r");
            if (!f_list) {
                fprintf(stderr, "%s: %s: %s\n", g_opts.progname, g_opts.files_from, strerror(errno));
                exit(1);
            }
        }

        char line_buf[4096];
        int delim = g_opts.files0 ? '\0' : '\n';

        while (1) {
            int idx = 0;
            int ch;
            while ((ch = fgetc(f_list)) != EOF && ch != delim) {
                if (idx < (int)sizeof(line_buf) - 1) {
                    line_buf[idx++] = (char)ch;
                }
            }
            if (ch == EOF && idx == 0) break;
            line_buf[idx] = '\0';
            if (line_buf[0] != '\0') {
                if (g_opts.mode == MODE_LIST) {
                    char *farr[1] = { line_buf };
                    list_files(1, farr);
                } else {
                    process_single_file(line_buf);
                }
            }
        }

        if (f_list != stdin) fclose(f_list);
        return g_opts.exit_status;
    }

    if (num_files == 0) {
        if (g_opts.mode == MODE_LIST) {
            fprintf(stderr, "%s: With --list, file names must be given on the command line\n", g_opts.progname);
            return 1;
        }
        process_single_file("-");
    } else {
        if (g_opts.mode == MODE_LIST) {
            int ret = list_files(num_files, &argv[file_args_start]);
            if (ret != 0 && g_opts.exit_status == 0) {
                g_opts.exit_status = 1;
            }
        } else {
            for (int i = file_args_start; i < argc; i++) {
                process_single_file(argv[i]);
            }
        }
    }

    return g_opts.exit_status;
}
