                else if (strcmp(optarg, "xz") == 0) g_opts.format = FORMAT_XZ;
                else if (strcmp(optarg, "lzma") == 0) g_opts.format = FORMAT_LZMA;
                else if (strcmp(optarg, "lzip") == 0) g_opts.format = FORMAT_LZIP;
                else if (strcmp(optarg, "raw") == 0) g_opts.format = FORMAT_RAW;
                else {
