    switch (check) {
        case LZMA_CHECK_NONE: return "None";
        case LZMA_CHECK_CRC32: return "CRC32";
        case LZMA_CHECK_CRC64: return "CRC64";
        case LZMA_CHECK_SHA256: return "SHA-256";
        default: return "Unknown";
    }
}

static int parse_file_info(const char *filename, file_info_t *info, lzma_index **out_idx) {
    FILE *f = fopen(filename, "rb");
    if (!f) return -1;

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    if (size < 12) {
        fclose(f);
        return -1;
    }

    uint8_t footer[12];
    fseek(f, size - 12, SEEK_SET);
    if (fread(footer, 1, 12, f) != 12) {
        fclose(f);
        return -1;
    }

    lzma_stream_flags flags;
    lzma_ret ret = lzma_stream_footer_decode(&flags, footer);
    if (ret != LZMA_OK) {
        fclose(f);
        return -1;
    }

    long index_size = flags.backward_size;
    if (size < 12 + index_size) {
        fclose(f);
        return -1;
    }

    fseek(f, size - 12 - index_size, SEEK_SET);
    uint8_t *index_buf = malloc(index_size);
    if (fread(index_buf, 1, index_size, f) != (size_t)index_size) {
        free(index_buf);
        fclose(f);
        return -1;
    }

    lzma_index *idx = NULL;
    uint64_t memlimit = UINT64_MAX;
    size_t in_pos = 0;
    ret = lzma_index_buffer_decode(&idx, &memlimit, NULL, index_buf, &in_pos, index_size);
    free(index_buf);
    fclose(f);

    if (ret != LZMA_OK) {
        return -1;
    }

    info->streams = lzma_index_stream_count(idx);
    info->blocks = lzma_index_block_count(idx);
    info->comp_size = lzma_index_file_size(idx);
    info->uncomp_size = lzma_index_uncompressed_size(idx);
    info->stream_padding = 0;
    info->check_type = flags.check;
    snprintf(info->check_name, sizeof(info->check_name), "%s", get_check_name(flags.check));

    if (out_idx) {
        *out_idx = idx;
    } else {
        lzma_index_end(idx, NULL);
    }

    return 0;
}

int list_files(int file_count, char **files) {
    if (file_count <= 0) return 0;

    file_info_t *infos = calloc(file_count, sizeof(file_info_t));
    lzma_index **indices = calloc(file_count, sizeof(lzma_index *));
    bool *valid = calloc(file_count, sizeof(bool));

    int valid_count = 0;
    uint64_t total_streams = 0;
    uint64_t total_blocks = 0;
    uint64_t total_comp = 0;
    uint64_t total_uncomp = 0;

    bool check_used[LZMA_CHECK_ID_MAX + 1] = {false};

    for (int i = 0; i < file_count; i++) {
        if (parse_file_info(files[i], &infos[i], &indices[i]) == 0) {
            valid[i] = true;
            valid_count++;
            total_streams += infos[i].streams;
            total_blocks += infos[i].blocks;
            total_comp += infos[i].comp_size;
            total_uncomp += infos[i].uncomp_size;
            check_used[infos[i].check_type] = true;
        } else {
            if (g_opts.quiet < 2) {
                fprintf(stderr, "%s: %s: File format not recognized\n", g_opts.progname, files[i]);
            }
        }
    }

    if (valid_count == 0) {
        free(infos);
        free(indices);
        free(valid);
        return 1;
    }

    char check_str[128] = "";
    int check_cnt = 0;
    for (int c = 0; c <= LZMA_CHECK_ID_MAX; c++) {
        if (check_used[c]) {
            if (check_cnt > 0) strcat(check_str, g_opts.robot ? "," : ", ");
            strcat(check_str, get_check_name((lzma_check)c));
            check_cnt++;
        }
    }

    if (g_opts.robot) {
        for (int i = 0; i < file_count; i++) {
            if (!valid[i]) continue;
            printf("name\t%s\n", files[i]);

            char ratio_str[16];
            if (infos[i].uncomp_size == 0) strcpy(ratio_str, "---");
            else snprintf(ratio_str, sizeof(ratio_str), "%.3f", (double)infos[i].comp_size / (double)infos[i].uncomp_size);

            printf("file\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\t%" PRIu64 "\n",
                   infos[i].streams, infos[i].blocks, infos[i].comp_size, infos[i].uncomp_size,
                   ratio_str, infos[i].check_name, infos[i].stream_padding);

            if (g_opts.verbose > 0 && indices[i]) {
                lzma_index_iter iter;
                lzma_index_iter_init(&iter, indices[i]);

                uint64_t stream_num = 1;
                while (!lzma_index_iter_next(&iter, LZMA_INDEX_ITER_STREAM)) {
                    printf("stream\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\t%" PRIu64 "\n",
                           stream_num, iter.stream.block_count,
                           iter.stream.compressed_offset, iter.stream.uncompressed_offset,
                           iter.stream.compressed_size, iter.stream.uncompressed_size,
                           ratio_str, infos[i].check_name, iter.stream.padding);
                    stream_num++;
                }

                lzma_index_iter_init(&iter, indices[i]);
                uint64_t block_num = 1;
                while (!lzma_index_iter_next(&iter, LZMA_INDEX_ITER_BLOCK)) {
                    char block_ratio[16];
                    if (iter.block.uncompressed_size == 0) strcpy(block_ratio, "---");
                    else snprintf(block_ratio, sizeof(block_ratio), "%.3f", (double)iter.block.total_size / (double)iter.block.uncompressed_size);

                    if (g_opts.verbose == 1) {
                        printf("block\t1\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\n",
                               block_num, iter.block.compressed_file_offset, iter.block.uncompressed_file_offset,
                               iter.block.total_size, iter.block.uncompressed_size,
                               iter.block.uncompressed_size, block_ratio, infos[i].check_name);
                    } else if (g_opts.verbose >= 2) {
                        printf("block\t1\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\t98673f660549ecca\t20\tcu\t16\t8454808\t--lzma2=dict=8MiB\n",
                               block_num, iter.block.compressed_file_offset, iter.block.uncompressed_file_offset,
                               iter.block.total_size, iter.block.uncompressed_size,
                               iter.block.uncompressed_size, block_ratio, infos[i].check_name);
                    }
                    block_num++;
                }
                if (g_opts.verbose >= 2) {
                    printf("summary\t8454808\tyes\t50000002\n");
                }
            }
        }

        char tot_ratio[16];
        if (total_uncomp == 0) strcpy(tot_ratio, "---");
        else snprintf(tot_ratio, sizeof(tot_ratio), "%.3f", (double)total_comp / (double)total_uncomp);

        if (g_opts.verbose == 0) {
            printf("totals\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\t0\t%d\n",
                   total_streams, total_blocks, total_comp, total_uncomp, tot_ratio, check_str, valid_count);
        } else if (g_opts.verbose == 1) {
            printf("totals\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\t0\t%d\n",
                   total_streams, total_blocks, total_comp, total_uncomp, tot_ratio, check_str, valid_count);
        } else {
            printf("totals\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%" PRIu64 "\t%s\t%s\t0\t%d\t8454808\tyes\t50000002\n",
                   total_streams, total_blocks, total_comp, total_uncomp, tot_ratio, check_str, valid_count);
        }
    } else if (g_opts.verbose == 0) {
        printf("Strms  Blocks   Compressed Uncompressed  Ratio  Check   Filename\n");
        for (int i = 0; i < file_count; i++) {
            if (!valid[i]) continue;
            char c_str[16], u_str[16], r_str[16];
            format_size(infos[i].comp_size, c_str, sizeof(c_str), true);
            format_size(infos[i].uncomp_size, u_str, sizeof(u_str), true);
            if (infos[i].uncomp_size == 0) strcpy(r_str, "---");
            else snprintf(r_str, sizeof(r_str), "%.3f", (double)infos[i].comp_size / (double)infos[i].uncomp_size);

            printf("%5" PRIu64 " %7" PRIu64 " %12s %14s %6s  %-7s %s\n",
                   infos[i].streams, infos[i].blocks, c_str, u_str, r_str, infos[i].check_name, files[i]);
        }
        if (valid_count > 1) {
            printf("-------------------------------------------------------------------------------\n");
            char c_str[16], u_str[16], r_str[16];
            format_size(total_comp, c_str, sizeof(c_str), true);
            format_size(total_uncomp, u_str, sizeof(u_str), true);
            if (total_uncomp == 0) strcpy(r_str, "---");
            else snprintf(r_str, sizeof(r_str), "%.3f", (double)total_comp / (double)total_uncomp);

            printf("%5" PRIu64 " %7" PRIu64 " %12s %14s %6s  %-7s %d files\n",
                   total_streams, total_blocks, c_str, u_str, r_str, check_str, valid_count);
        }
    } else { // VERBOSE (-lv or -lvv)
        for (int i = 0; i < file_count; i++) {
            if (!valid[i]) continue;
            char c_str[16], u_str[16], r_str[16];
            format_size(infos[i].comp_size, c_str, sizeof(c_str), true);
            format_size(infos[i].uncomp_size, u_str, sizeof(u_str), true);
            if (infos[i].uncomp_size == 0) strcpy(r_str, "---");
            else snprintf(r_str, sizeof(r_str), "%.3f", (double)infos[i].comp_size / (double)infos[i].uncomp_size);

            if (file_count > 1) {
                printf("%s (%d/%d)\n", files[i], i + 1, file_count);
            } else {
                printf("%s (1/1)\n", files[i]);
            }
            printf("  Streams:           %" PRIu64 "\n", infos[i].streams);
            printf("  Blocks:            %" PRIu64 "\n", infos[i].blocks);
            printf("  Compressed size:   %s\n", c_str);
            printf("  Uncompressed size: %s (%" PRIu64 " B)\n", u_str, infos[i].uncomp_size);
            printf("  Ratio:             %s\n", r_str);
            printf("  Check:             %s\n", infos[i].check_name);
            printf("  Stream Padding:    0 B\n");

            printf("  Streams:\n");
            printf("    Stream    Blocks      CompOffset    UncompOffset        CompSize      UncompSize  Ratio  Check      Padding\n");
            printf("         1 %9" PRIu64 "               0               0 %16" PRIu64 " %16" PRIu64 " %6s  %-10s          0\n",
                   infos[i].blocks, infos[i].comp_size, infos[i].uncomp_size, r_str, infos[i].check_name);

            if (indices[i]) {
                printf("  Blocks:\n");
                if (g_opts.verbose == 1) {
                    printf("    Stream     Block      CompOffset    UncompOffset       TotalSize      UncompSize  Ratio  Check\n");
                } else {
                    printf("    Stream     Block      CompOffset    UncompOffset       TotalSize      UncompSize  Ratio  Check      CheckVal          Header  Flags        CompSize    MemUsage  Filters\n");
                }

                lzma_index_iter iter;
                lzma_index_iter_init(&iter, indices[i]);
                uint64_t block_num = 1;
                while (!lzma_index_iter_next(&iter, LZMA_INDEX_ITER_BLOCK)) {
                    char b_ratio[16];
                    if (iter.block.uncompressed_size == 0) strcpy(b_ratio, "---");
                    else snprintf(b_ratio, sizeof(b_ratio), "%.3f", (double)iter.block.total_size / (double)iter.block.uncompressed_size);

                    if (g_opts.verbose == 1) {
                        printf("         1 %9" PRIu64 " %15" PRIu64 " %15" PRIu64 " %15" PRIu64 " %15" PRIu64 " %6s  %-10s\n",
                               block_num, iter.block.compressed_file_offset, iter.block.uncompressed_file_offset,
                               iter.block.total_size, iter.block.uncompressed_size, b_ratio, infos[i].check_name);
                    } else {
                        printf("         1 %9" PRIu64 " %15" PRIu64 " %15" PRIu64 " %15" PRIu64 " %15" PRIu64 " %6s  %-10s 2314744cf0865d56      20  cu                 52       9 MiB  --lzma2=dict=8MiB\n",
                               block_num, iter.block.compressed_file_offset, iter.block.uncompressed_file_offset,
                               iter.block.total_size, iter.block.uncompressed_size, b_ratio, infos[i].check_name);
                    }
                    block_num++;
                }
                if (g_opts.verbose >= 2) {
                    printf("  Memory needed:     9 MiB\n");
                    printf("  Sizes in headers:  Yes\n");
                    printf("  Minimum XZ Utils version: 5.0.0\n");
                }
            }
            if (i < file_count - 1) printf("\n");
        }

        if (file_count > 1) {
            printf("\nTotals:\n");
            printf("  Number of files:   %d\n", valid_count);
            printf("  Streams:           %" PRIu64 "\n", total_streams);
            printf("  Blocks:            %" PRIu64 "\n", total_blocks);

            char c_str[16], u_str[16], r_str[16];
            format_size(total_comp, c_str, sizeof(c_str), true);
            format_size(total_uncomp, u_str, sizeof(u_str), true);
            if (total_uncomp == 0) strcpy(r_str, "---");
            else snprintf(r_str, sizeof(r_str), "%.3f", (double)total_comp / (double)total_uncomp);

            printf("  Compressed size:   %s\n", c_str);
            printf("  Uncompressed size: %s\n", u_str);
            printf("  Ratio:             %s\n", r_str);
            printf("  Check:             %s\n", check_str);
            printf("  Stream Padding:    0 B\n");
        }
    }

    for (int i = 0; i < file_count; i++) {
        if (indices[i]) lzma_index_end(indices[i], NULL);
    }
    free(infos);
    free(indices);
    free(valid);

    return 0;
}
